-- Forty-eight retained source boundary assertions on the actual managed rail.
-- Synthetic data and rollback only; no provider, physical stock or lifecycle claim.
BEGIN;
SET LOCAL row_security=on;
SELECT plan(48);
SELECT ok(NOT (rolcanlogin OR rolsuper OR rolcreatedb OR rolcreaterole OR rolinherit OR rolreplication OR rolbypassrls),'closed writer cannot log in or expand authority') FROM pg_roles WHERE rolname='openlup_channel_purchase_writer';
SELECT is((SELECT count(*)::int FROM pg_auth_members m WHERE (m.roleid='openlup_channel_purchase_writer'::regrole OR m.member='openlup_channel_purchase_writer'::regrole) AND NOT
 (m.roleid='openlup_channel_purchase_writer'::regrole AND m.member=(SELECT proowner FROM pg_proc WHERE oid='public.channel_purchase_scope(jsonb,uuid,uuid,boolean,uuid)'::regprocedure)
  AND m.grantor=10 AND m.admin_option AND NOT m.set_option AND NOT m.inherit_option AND EXISTS(SELECT 1 FROM pg_roles r WHERE r.oid=m.member AND r.rolcreaterole AND NOT r.rolsuper))),0,'no forbidden role reaches closed writer; existing installer ADMIN-only edge retained');
