SELECT ok(NOT has_function_privilege('openlup_mcp_reader','public.channel_ingest_capture_read(uuid,text,uuid)','EXECUTE'),'MCP cannot read protected capture');
SELECT ok(NOT has_function_privilege('service_role','public.channel_purchase_scope(jsonb,uuid,uuid,boolean,uuid)','EXECUTE'),'runtime cannot invoke private scope');
SELECT ok((SELECT convalidated FROM pg_constraint WHERE conname='channel_pull_page_ref'),'page reference validated');
SELECT ok(has_function_privilege('service_role','public.channel_purchase_conversion_command(uuid,text,uuid,uuid,text)','EXECUTE'),'service can recover sealed command');
SELECT ok(NOT has_function_privilege('authenticated','public.channel_purchase_conversion_command(uuid,text,uuid,uuid,text)','EXECUTE'),'browser cannot use command slot');
SELECT ok(has_function_privilege('openlup_channel_purchase_writer','public.channel_control_ref(text)','EXECUTE'),'closed owner can validate references');
SELECT ok(NOT EXISTS(SELECT 1 FROM unnest(ARRAY['anon','authenticated','service_role','openlup_mcp_reader']) r WHERE has_function_privilege(r,'public.channel_control_ref(text)','EXECUTE')),'raw roles cannot call private validator');
SELECT ok(NOT has_any_column_privilege('openlup_channel_purchase_writer','public.platform_job_runs','SELECT,INSERT,UPDATE,REFERENCES') AND NOT has_any_column_privilege('openlup_channel_purchase_writer','public.platform_job_controls','SELECT,INSERT,UPDATE,REFERENCES'),'closed writer has no raw job authority');
SELECT ok(prosecdef AND proowner<>'openlup_channel_purchase_writer'::regrole,'live-job scope retains installer authority') FROM pg_proc WHERE oid='public.channel_purchase_scope(jsonb,uuid,uuid,boolean,uuid)'::regprocedure;
SET LOCAL ROLE service_role;
SELECT throws_ok($$SELECT public.channel_control_ref('synthetic')$$,'42501','permission denied for function channel_control_ref','service validator call denied');
SELECT throws_ok($$SELECT public.channel_purchase_scope(NULL,NULL,NULL,false,NULL)$$,'42501','permission denied for function channel_purchase_scope','service scope call denied');
